<script>const cfg=<?=json_encode($config,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const token=localStorage.getItem('admin_token')||sessionStorage.getItem('admin_token')||'';const clear=()=>{localStorage.removeItem('admin_token');sessionStorage.removeItem('admin_token');};const login=()=>location.replace(cfg.loginUrl);const esc=v=>String(v??'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function start(){if(!token)return login();try{const guard=await fetch(cfg.apiDashboardUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});if(!guard.ok){clear();return login();}const guardData=await guard.json();const section=<?=json_encode($key)?>;if(section==='profil'){const a=guardData.auth||{};document.getElementById('resourceHead').innerHTML='<tr><th>Informasi</th><th>Detail</th></tr>';document.getElementById('resourceRows').innerHTML='<tr><td>Username</td><td>'+esc(a.username||'-')+'</td></tr><tr><td>ID Admin</td><td>'+esc(a.id||a.sub||'-')+'</td></tr><tr><td>Role</td><td>'+esc(a.role||'admin')+'</td></tr>';document.getElementById('resourceMessage').textContent='Profil admin yang sedang login.';return;}const res=await fetch(cfg.apiUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});const json=await res.json();if(!res.ok)throw new Error(json.message||'Gagal memuat data.');const rows=Array.isArray(json.data)?json.data:(json.data?[json.data]:[]);if(section==='kategori'){const categoryPhoto=name=>{const n=String(name||'').toLocaleLowerCase('id-ID');if(n.includes('alam')||n.includes('gunung'))return '../assets/images/telaga.png?v=20261112-exact';if(n.includes('air')||n.includes('curug')||n.includes('air terjun'))return '../assets/images/kategori-air-curug.jpeg?v=20261112-exact';if(n.includes('buatan')||n.includes('kuliner'))return '../assets/images/kategori-buatan-kuliner.jpeg?v=20261112-exact';if(n.includes('sejarah')||n.includes('budaya'))return '../assets/images/kategori-sejarah-budaya.jpeg?v=20261112-exact';return '../assets/images/img.png';};document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Foto</th><th>Kategori</th><th>Jumlah Wisata</th></tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map((r,i)=>'<tr><td class="kategori-number" data-label="No">'+(i+1)+'</td><td class="kategori-photo" data-label="Foto"><img src="'+categoryPhoto(r.name)+'" alt="Foto '+esc(r.name)+'" loading="lazy"></td><td class="kategori-name" data-label="Kategori">'+esc(r.name)+'</td><td class="kategori-total" data-label="Jumlah wisata">'+esc(r.total_destinations??0)+'</td></tr>').join(''):'<tr><td colspan="4" class="text-center py-4">Belum ada data kategori.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' kategori).';}else{let cols=section==='fasilitas'?['id','name','icon_code','description']:section==='pengguna'?['id','nama','email','no_telepon']:['id_ulasan','nama_pengguna','nama_wisata','rating','komentar','tanggal_ulasan'];document.getElementById('resourceHead').innerHTML='<tr>'+cols.map(c=>'<th>'+esc(c.replaceAll('_',' '))+'</th>').join('')+'</tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+cols.length+'" class="text-center py-4">Belum ada data.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' data).';}}catch(e){document.getElementById('resourceMessage').textContent=e.message||'Terjadi kesalahan.';}}
async function logout(){try{await fetch(cfg.apiLogoutUrl,{method:'POST',headers:{Authorization:'Bearer '+token}});}finally{clear();login();}}document.getElementById('logoutButton').onclick=logout;document.getElementById('mobileLogoutButton').onclick=logout;document.getElementById('sidebarCollapse').onclick=()=>document.body.classList.toggle('sidebar-collapsed');document.getElementById('mobileMenuButton').onclick=()=>document.body.classList.toggle('mobile-sidebar-open');document.getElementById('sidebarBackdrop').onclick=()=>document.body.classList.remove('mobile-sidebar-open');start();</script></body></html>
